package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.List;
import java.util.Locale;

/** Detects story-sized tensions already present in state. It never predetermines an ending. */
public final class EmergentCampaignDirector {
    private final AppDb db;private final LivingSettlementEngine settlements;private final RumorNetworkEngine rumors;private final WorldHistoryEngine history;
    public EmergentCampaignDirector(AppDb database){db=database;settlements=new LivingSettlementEngine(database);rumors=new RumorNetworkEngine(database);history=new WorldHistoryEngine(database);AppDb.ensureSixZeroSchema(db.getWritableDatabase());}
    public synchronized JSONObject refresh(){JSONObject out=new JSONObject();int upserts=0;try{int day=Math.max(1,db.getSceneState().optInt("day_number",1));history.ingestCanonicalFacts();settlements.simulateToDay(day);rumors.update(day);
        for(JSONObject f:db.listFactions(60)){String plan=f.optString("current_plan").trim();if(plan.isEmpty())continue;int momentum=Math.max(10,Math.min(100,f.optInt("plan_progress",0)));JSONObject arc=arc("faction:"+f.optLong("id")+":"+shortHash(plan),"A ambição de "+f.optString("name"),"A facção move recursos para "+plan,"Até onde "+f.optString("name")+" conseguirá avançar antes que alguém altere o equilíbrio?",momentum,Math.max(20,momentum),new JSONArray().put(f.optString("name")),new JSONArray().put("Plano persistente: "+plan),new JSONArray().put("o plano avança").put("o plano é desviado").put("uma terceira força aproveita a tensão"),day);upsert(arc);upserts++;}
        for(JSONObject c:db.listWorldClocks(true,60)){int cur=c.optInt("current_value",0),max=Math.max(1,c.optInt("max_value",6));if(cur<=0)continue;int m=(int)Math.round(100d*cur/max);JSONObject arc=arc("clock:"+c.optLong("id"),c.optString("title","Relógio em movimento"),c.optString("description","Um processo do mundo está avançando."),"O que acontecerá quando este processo alcançar seu limiar?",m,Math.max(15,m),new JSONArray(),new JSONArray().put("Relógio "+cur+"/"+max),new JSONArray().put("é interrompido").put("é acelerado").put("chega ao limite e produz consequência"),day);upsert(arc);upserts++;}
        for(JSONObject s:settlements.list(80)){int pressure=Math.max(s.optInt("unrest"),Math.max(s.optInt("scarcity"),100-s.optInt("security")));if(pressure<55)continue;String cause=s.optInt("scarcity")>=pressure?"escassez":(s.optInt("unrest")>=pressure?"agitação":"insegurança");JSONObject arc=arc("settlement:"+s.optString("settlement_key")+":"+cause,"Crise em "+s.optString("name"),"A "+cause+" está alterando o cotidiano e as relações de poder em "+s.optString("name")+".","Quem se beneficiará — e quem pagará — se a crise continuar?",pressure,pressure,new JSONArray().put(s.optString("name")),new JSONArray().put(cause+" "+pressure+"/100"),new JSONArray().put("a cidade se adapta").put("a crise se agrava").put("uma facção assume o controle da resposta"),day);upsert(arc);upserts++;}
        upserts+=deriveConvergenceArcs(day);
        out.put("upserts",upserts).put("active",list(30)).put("history",history.context()).put("rumors",rumors.context());}catch(Exception e){try{out.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}}return out;}
    private int deriveConvergenceArcs(int day){int count=0;JSONArray events=history.important(100);java.util.LinkedHashMap<String,JSONArray> byPlace=new java.util.LinkedHashMap<String,JSONArray>();java.util.LinkedHashMap<String,JSONArray> byActor=new java.util.LinkedHashMap<String,JSONArray>();for(int i=0;i<events.length();i++){JSONObject event=events.optJSONObject(i);if(event==null)continue;String place=event.optString("location").trim();if(!place.isEmpty())byPlace.computeIfAbsent(place,k->new JSONArray()).put(event);try{JSONArray actors=new JSONArray(event.optString("actors_json","[]"));for(int a=0;a<actors.length();a++){String actor=actors.optString(a).trim();if(actor.length()<3)continue;byActor.computeIfAbsent(actor,k->new JSONArray()).put(event);}}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}}
        for(java.util.Map.Entry<String,JSONArray> entry:byPlace.entrySet()){if(entry.getValue().length()<3)continue;JSONArray evidence=evidence(entry.getValue(),5),actors=actors(entry.getValue(),8);int momentum=Math.min(90,25+entry.getValue().length()*8);try{upsert(arc("convergence:place:"+shortHash(entry.getKey()),"Convergência em "+entry.getKey(),"Vários acontecimentos independentes passaram a se cruzar em "+entry.getKey()+".","Que nova ordem surgirá quando essas forças finalmente se encontrarem?",momentum,Math.min(95,momentum+10),actors,evidence,new JSONArray().put("as tensões se conectam").put("um ator quebra a cadeia causal").put("um conflito menor revela uma causa maior"),day));count++;}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}}
        for(java.util.Map.Entry<String,JSONArray> entry:byActor.entrySet()){if(entry.getValue().length()<3)continue;JSONArray evidence=evidence(entry.getValue(),5);int momentum=Math.min(88,20+entry.getValue().length()*9);try{upsert(arc("convergence:actor:"+shortHash(entry.getKey()),"A influência de "+entry.getKey(),"Ações separadas voltam repetidamente a envolver "+entry.getKey()+".","O papel de "+entry.getKey()+" será transformado, revelado ou encerrado pelas consequências acumuladas?",momentum,momentum,new JSONArray().put(entry.getKey()),evidence,new JSONArray().put("sua influência cresce").put("alianças mudam sua trajetória").put("consequências anteriores retornam de forma inesperada"),day));count++;}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}}
        return count;}
    private static JSONArray evidence(JSONArray events,int limit){JSONArray out=new JSONArray();for(int i=0;i<Math.min(limit,events.length());i++){JSONObject e=events.optJSONObject(i);if(e!=null)out.put(e.optString("title")+": "+e.optString("summary"));}return out;}
    private static JSONArray actors(JSONArray events,int limit){JSONArray out=new JSONArray();java.util.HashSet<String> seen=new java.util.HashSet<String>();for(int i=0;i<events.length()&&out.length()<limit;i++){JSONObject e=events.optJSONObject(i);if(e==null)continue;try{JSONArray a=new JSONArray(e.optString("actors_json","[]"));for(int j=0;j<a.length()&&out.length()<limit;j++){String n=a.optString(j).trim();if(n.length()>2&&seen.add(n.toLowerCase(Locale.ROOT)))out.put(n);}}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}}return out;}

    private JSONObject arc(String key,String title,String premise,String question,int momentum,int urgency,JSONArray actors,JSONArray evidence,JSONArray consequences,int day)throws Exception{return new JSONObject().put("arc_key",key).put("title",title).put("premise",premise).put("dramatic_question",question).put("stage",stage(momentum)).put("momentum",momentum).put("urgency",urgency).put("actors_json",actors.toString()).put("evidence_json",evidence.toString()).put("possible_consequences_json",consequences.toString()).put("origin_json",new JSONObject().put("generated_from_state",true).toString()).put("status","active").put("created_day",day).put("updated_day",day);}
    private void upsert(JSONObject a){ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());String[] fields={"arc_key","title","premise","dramatic_question","stage","actors_json","evidence_json","possible_consequences_json","origin_json","status"};for(String f:fields)v.put(f,a.optString(f));v.put("momentum",a.optInt("momentum"));v.put("urgency",a.optInt("urgency"));v.put("created_day",a.optInt("created_day",1));v.put("updated_day",a.optInt("updated_day",1));v.put("created_at",System.currentTimeMillis());v.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().insertWithOnConflict("emergent_arcs",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    public JSONArray list(int limit){return new JSONArray(db.queryList("SELECT * FROM emergent_arcs WHERE world_profile=? AND status='active' ORDER BY urgency DESC,momentum DESC,updated_at DESC LIMIT "+Math.max(1,Math.min(200,limit)),new String[]{db.getActiveMapProfile()}));}
    public JSONObject context(){JSONObject o=new JSONObject();try{o.put("active_arcs",list(18)).put("director_contract","Arcos emergem de estado persistido. Eles oferecem perguntas e tensões, nunca roteiro ou desfecho obrigatório.");}catch(Exception ignored){AppLog.ignored("EmergentCampaignDirector","Falha tolerada na camada 6.0.",ignored);}return o;}
    private static String stage(int m){return m>=85?"climax":m>=60?"escalating":m>=30?"developing":"germinating";}
    private static String shortHash(String s){return Integer.toHexString((s==null?"":s).hashCode());}
}
